mapper.select:
SELECT t.* FROM agri_prod_task_info t
WHERE t.deleted = 0 AND t.tenant_id = #{tenantId}

    AND t.task_name LIKE CONCAT('%', #{dto.taskName}, '%')


    AND t.task_type = #{dto.taskType}


    AND t.farm_id = #{dto.farmId}


    AND t.plot_id = #{dto.plotId}


    AND t.executor_id = #{dto.executorId}


    AND t.status = #{dto.status}


    AND t.priority = #{dto.priority}


    AND DATE(t.plan_start_time) >= #{dto.startDate}


    AND DATE(t.plan_end_time) <= #{dto.endDate}

ORDER BY t.plan_start_time DESC
